    reply=AUDIT/'GPT_COOKING_EXACT_REVIEW.txt';text=reply.read_text(encoding='utf-8');assert 'After those five edits' in text and '44/44 Cooking set may be marked REVIEWED' in text
    paths=[ROOT/'docs/mechanics/COOKING_RECIPE_PLAYTEST.md',ROOT/'docs/mechanics/COOKING_PUBLIC_RECIPE_CARDS.md',ROOT/'docs/director-only/COOKING_INTERNAL_RECIPE_CARDS.md',ROOT/'data/playtest/cooking_recipe_candidate.json',ROOT/'data/director/cooking_recipe_candidate_internal.json']
    label='REVIEWED provisional authored operational PLAYTEST Cooking recipe set'
